  ('e2000000-0000-4000-b000-0000000041c8', 'e2000000-0000-4000-a000-000000000694', 0, 'Procura entender o próximo, assumindo atitudes positivas como simpatia, empatia, honestidade, compaixão, confiança e solidariedade, o que caracteriza o valor da igualdade.', false),
  ('e2000000-0000-4000-b000-0000000041c9', 'e2000000-0000-4000-a000-000000000694', 1, 'Faz com que todos possam ser iguais e receber o mesmo tratamento, assegurando imparcialidade, oportunidades e tratamentos iguais para todos, o que caracteriza o valor da amizade.', false),
  ('e2000000-0000-4000-b000-0000000041ca', 'e2000000-0000-4000-a000-000000000694', 2, 'Dá o melhor de si na vivência das diversas atividades relacionadas ao esporte ou aos jogos, participando e progredindo de acordo com seus objetivos, o que caracteriza o valor da coragem.', false),
  ('e2000000-0000-4000-b000-0000000041cb', 'e2000000-0000-4000-a000-000000000694', 3, 'Manifesta a habilidade de enfrentar a dor, o sofrimento, o medo, a incerteza e a intimidação nas atividades, agindo corretamente contra a vergonha, a desonra e o desânimo, o que caracteriza o valor da determinação.', false),
  ('e2000000-0000-4000-b000-0000000041cc', 'e2000000-0000-4000-a000-000000000694', 4, 'Inclui em suas ações o fair play (jogo limpo), a honestidade, o sentimento positivo de consideração por outra pessoa, o conhecimento dos seus limites, a valorização de sua própria saúde e o combate ao doping, o que caracteriza o valor do respeito.', true),
